      "id": "b2-bebauen",
      "layout": "standardStudy",
      "translation": "bebygge • dyrke",
      "explanation": [
        "Hovedtanke: bebauen er et verb med to betydninger: å bebygge en tomt med bygninger og å dyrke jorda, en åker, i landbruket. Det er ikke delbart og tar akkusativ.",
        "Former: bebaut, bebaute, hat bebaut. Partisippet bebaut brukes ofte som adjektiv: dicht bebaut (tett bebygd), unbebaut (ubebygd). Om bygninger sier man mit Häusern bebauen.",
        "Om åkrer brukes også anbauen (dyrke en vekst): Weizen anbauen; bebauen er videre og gjelder dyrking av jorda generelt."
      ],
      "examples": [
        {
          "de": "Das Grundstück wird mit Wohnhäusern bebaut.",
          "lv": "Tomten bebygges med bolighus."
        },
        {
          "de": "Die Bauern bebauen das Feld mit Weizen.",
          "lv": "Bøndene dyrker hvete på åkeren."
        },
        {
          "de": "Das Gelände darf nicht bebaut werden.",
          "lv": "Området må ikke bebygges."
        },
        {
          "de": "Der Hang ist dicht bebaut.",
          "lv": "Skråningen er tett bebygd."
        }
      ],
      "comparison": [
        {
          "word": "bauen",
          "meaning": "bygge",
          "example": "Sie bauen ein Haus. – De bygger et hus."
        },
        {
          "word": "anbauen",
          "meaning": "dyrke, bygge på",
          "example": "Hier baut man Wein an. – Her dyrker man vin."
        },
        {
          "word": "bearbeiten",
          "meaning": "bearbeide",
          "example": "Er bearbeitet den Boden. – Han bearbeider jorda."
        }
      ],
      "tip": [
        "I betydningen bygninger brukes mit: mit Häusern bebauen; man ser det også ofte i passiv: bebaut werden.",
        "Motsetningen er unbebaut – ubebygd."
      ],
      "important": [
        "Bebauen er ikke det samme som bauen: bauen er å bygge noe, bebauen å dekke et område med bygninger.",
        "I landbruket brukes anbauen oftere om å dyrke planter."
      ],
