      "layout": "standardStudy",
      "translation": "befatte seg med • beskjeftige seg med",
      "explanation": [
        "Hovedtanke: sich befassen er et refleksivt verb som betyr å befatte seg med eller ta for seg et spørsmål eller et emne, ofte skriftlig eller profesjonelt. Etter mit følger dativ: sich mit etwas befassen.",
        "Former: befasst sich, befasste sich, hat sich befasst. Forstavelsen be- er ikke delbar, derfor er det ingen ge-.",
        "Ordet låter mer formelt enn sich beschäftigen; det brukes om komiteer, studier, domstoler og mennesker som undersøker et spørsmål."
      ],
      "examples": [
        {
          "de": "Ich befasse mich mit der Geschichte der Stadt.",
          "lv": "Jeg beskjeftiger meg med byens historie."
        },
        {
          "de": "Der Ausschuss befasst sich mit dem Problem.",
          "lv": "Komiteen befatter seg med problemet."
        },
        {
          "de": "Damit habe ich mich noch nie befasst.",
          "lv": "Det har jeg aldri befattet meg med."
        },
        {
          "de": "Die Studie befasst sich mit den Folgen des Klimawandels.",
          "lv": "Studien tar for seg følgene av klimaendringene."
        }
      ],
      "comparison": [
        {
          "word": "sich beschäftigen mit",
          "meaning": "beskjeftige seg med, holde på med",
          "example": "Er beschäftigt sich mit Musik. – Han driver med musikk."
        },
        {
          "word": "sich auseinandersetzen mit",
          "meaning": "sette seg inn i, ta et oppgjør med",
          "example": "Wir setzen uns mit dem Thema auseinander. – Vi setter oss inn i temaet."
        },
        {
          "word": "behandeln",
          "meaning": "behandle, ta for seg",
          "example": "Das Buch behandelt dieses Thema. – Boka behandler dette temaet."
        }
      ],
      "tip": [
        "Etter mit brukes dativ: mit dem Thema, mit der Frage.",
        "Vil du si det enklere, kan du bruke sich beschäftigen mit, som betyr det samme."
      ],
      "important": [
        "I perfektum heter det hat sich befasst, ikke hat sich gebefasst: be- er en forstavelse som ikke kan skilles fra verbet.",
        "Sich befassen gjelder mer tenkning og drøfting enn fysisk aktivitet."
      ],
