      "translation": "framstilling • skildring • avbildning",
      "explanation": [
        "Hovedtanke: die Darstellung er et substantiv i hunkjønn, dannet av verbet darstellen. Det betyr en framstilling eller avbildning av noe: det et menneske sier, skriver, tegner eller spiller.",
        "Flertall er die Darstellungen. Betydninger: framstilling (beskrivelse av hendelser med ord), avbildning (i en tegning, et diagram: grafische Darstellung), tolkning (en skuespillers tolkning av en rolle).",
        "Vanlige forbindelser: eine Darstellung geben (gi en framstilling), die Darstellung der Ereignisse, die grafische Darstellung (grafisk framstilling)."
      ],
      "examples": [
        {
          "de": "Die Darstellung des Unfalls war sehr genau.",
          "lv": "Framstillingen av ulykken var svært nøyaktig."
        },
        {
          "de": "Die Zeitung gibt eine einseitige Darstellung der Ereignisse.",
          "lv": "Avisen gir en ensidig framstilling av hendelsene."
        },
        {
          "de": "Die Darstellung des Hamlet durch den jungen Schauspieler war beeindruckend.",
          "lv": "Den unge skuespillerens tolkning av Hamlet var imponerende."
        },
        {
          "de": "Die grafische Darstellung zeigt die Entwicklung der Preise.",
          "lv": "Den grafiske framstillingen viser prisutviklingen."
        }
      ],
      "comparison": [
        {
          "word": "die Beschreibung",
          "meaning": "beskrivelse",
          "example": "Die Beschreibung ist genau. – Beskrivelsen er nøyaktig."
        },
        {
          "word": "der Bericht",
          "meaning": "rapport, beretning",
          "example": "Der Bericht ist kurz. – Rapporten er kort."
        },
        {
          "word": "die Schilderung",
          "meaning": "levende skildring",
          "example": "Seine Schilderung war lebendig. – Skildringen hans var levende."
        }
      ],
      "tip": [
        "Etter Darstellung følger ofte von eller genitiv: die Darstellung des Problems, die Darstellung von Daten.",
        "Om et diagram eller en figur sier man grafische Darstellung."
      ],
      "important": [
        "Darstellung er ikke det samme som Beschreibung: Beschreibung er en beskrivelse med ord, mens Darstellung også kan være en tegning, et diagram eller en rolletolkning.",
        "Die Darstellung er hunkjønn, i flertall die Darstellungen."
      ],
