        "Uatskillelig prefiks ver-: verfügt, verfügte, hat verfügt. Etter verbet kan det komme akkusativ (eine Ausgangssperre verfügen) eller en dass-setning.",
        "En egen konstruksjon er verfügen über + akkusativ, som betyr at man har noe til rådighet: über Erfahrung verfügen — ha erfaring."
