        "Former: wechselt, wechselte, hat gewechselt. Det transitive verbet styrer akkusativ: etwas wechseln. Ved bytte over til noe nytt brukes preposisjonene in/auf/zu: Er wechselt zu einem anderen Verein.",
        "Substantivet er der Wechsel (skifte, bytte). Gjør man noe annerledes (i stedet for å erstatte det), bruker man oftere ändern eller sich verändern."
